#!/usr/bin/env bash
set -euo pipefail

# The bs58-encoded transactions below were generated by:
#   cargo run --example txn -p gobble-lib
# Each invokes the router program with a different target (gobble, amm, gobble-solana).
# Signatures are dummies — the CLI only needs the message structure for simulation.

RPC="${RPC_URL:-https://api.mainnet-beta.solana.com}"

cargo build -p gobble

echo "=== Test 1: Router -> Gobble (TRUE POSITIVE) ==="
echo "    Expected: forbidden access DETECTED"
echo ""
./target/debug/gobble \
  '' \
  -f 8-16 \
  --rpc-url "$RPC" \
  || true

echo ""
echo "=== Test 2: Router -> AMM (TRUE NEGATIVE) ==="
echo "    Expected: forbidden access NOT detected"
echo ""
./target/debug/gobble \
  '' \
  -f 8-16 \
  --rpc-url "$RPC" \
  || true

echo ""
echo "=== Test 3: Router -> GobbleSolana (FALSE POSITIVE) ==="
echo "    Expected: forbidden access DETECTED (false positive from deserialization)"
echo ""
./target/debug/gobble \
  '' \
  -f 8-16 \
  --rpc-url "$RPC" \
  || true
